import {stabilityReplicas} from './stability-replicas.mjs';
import {projectEllipsoid,rotateLatent,orientLatentProjection} from './spatial-lab.mjs';
import {convexHull3D,minimumVolumeEnclosingEllipsoid3D} from './geometry3d.mjs';

const replicaEscape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const replicaNumber=x=>Number.isFinite(x)?Number(x).toFixed(3):'—';
const replicaVector=x=>x?x.map(replicaNumber).join(', '):'等待训练';

// Imported values are used directly; no browser optimizer fabricates real fits.
export function validateReplicas(bundle){
  const fail=message=>{throw Error(message);};
  if(bundle?.format!=='regvelo-replicas-v1')fail('结果格式应为 regvelo-replicas-v1。');
  const data=bundle.data,n=data?.cells?.length;
  const genes=Array.isArray(data?.genes)?data.genes:[],featureOrder=Array.isArray(data?.featureOrder)?data.featureOrder:[],inputDim=genes.length*2;
  const expectedFeatures=[...genes.map(g=>`S_${g}`),...genes.map(g=>`U_${g}`)];
  if(!Number.isInteger(n)||n<12||n>10000||genes.length<1||featureOrder.length!==inputDim||JSON.stringify(featureOrder)!==JSON.stringify(expectedFeatures))fail(`需要 ${genes.length||'有效数量的'} 基因、${inputDim||'对应'} 维 S/U 表达及至少 12 个细胞。`);
  const matrix=(a,rows,cols,positive=false)=>Array.isArray(a)&&a.length===rows&&a.every(row=>Array.isArray(row)&&row.length===cols&&row.every(v=>Number.isFinite(v)&&(!positive||v>0)));
  if(new Set(data.cells.map(c=>c.id)).size!==n||!data.cells.every(c=>typeof c.id==='string'&&matrix([c.raw],1,inputDim)&&c.raw.every(v=>v>=0)))fail(`细胞 ID 或 ${inputDim} 维观测无效。`);
  const expectedModelCount=Number.isInteger(bundle.expectedModelCount)?bundle.expectedModelCount:3;
  if(!Array.isArray(bundle.models)||bundle.models.length>expectedModelCount)fail(`模型数必须为 0 至 ${expectedModelCount}。`);
  const indices=new Set();let hash,split;
  for(const m of bundle.models){
    if(!Number.isInteger(m.index)||m.index<0||m.index>=expectedModelCount||indices.has(m.index)||m.implementation!=='complete-local-regvelo')fail('需要互异的完整 RegVelo 模型索引。');
    indices.add(m.index);
    if(!/^[a-f0-9]{64}$/.test(m.observationSha256??'')||hash&&hash!==m.observationSha256)fail('模型的观测数据摘要不一致。');
    hash=m.observationSha256;
    const s=JSON.stringify(m.split);
    if(!m.split?.train?.length||!m.split?.validation?.length||split&&split!==s)fail('三个模型必须共享训练和验证划分。');
    split=s;
    const all=[...m.split.train,...m.split.validation];
    if(new Set(all).size!==n||all.length!==n||all.some(i=>!Number.isInteger(i)||i<0||i>=n))fail('训练和验证索引无效。');
    if(m.config?.n_latent!==3||!Number.isInteger(m.config.n_hidden)||m.config.n_hidden<8||!Number.isFinite(m.config.t_max)||!m.source?.module||!m.source?.model)fail('缺少三维配置或源码记录。');
    if(!matrix(m.mu,n,3)||!matrix(m.variance,n,3,true)||!matrix(m.initial?.mu,n,3)||!matrix(m.initial?.variance,n,3,true))fail('μ/v 维度或数值无效。');
    const pass=p=>p&&matrix(p.prediction,n,inputDim)&&matrix(p.time,n,genes.length);
    if(!pass(m.meanPass)||!Array.isArray(m.samples)||m.samples.length<2||m.samples.length>100)fail('缺少均值前向或后验样本。');
    for(const p of m.samples){
      if(!pass(p)||!matrix(p.epsilon,n,3)||!matrix(p.z,n,3))fail('后验样本维度无效。');
      for(let i=0;i<n;i++)for(let j=0;j<3;j++)if(Math.abs(p.z[i][j]-m.mu[i][j]-Math.sqrt(m.variance[i][j])*p.epsilon[i][j])>1e-4*(1+Math.abs(p.z[i][j])))fail('z 与重参数化公式不一致。');
    }
    const h=m.config.n_hidden;
    if(!matrix(m.encoder?.hidden,n,h)||!matrix(m.encoder?.input,n,inputDim)||!matrix(m.encoder?.meanWeight,3,h)||!matrix(m.encoder?.varianceWeight,3,h)||!matrix([m.encoder?.meanBias],1,3)||!matrix([m.encoder?.varianceBias],1,3)||!Number.isFinite(m.encoder?.varianceEpsilon))fail('编码器导出不完整。');
    if(!matrix(m.timeDecoder?.hiddenMu,n,h)||!matrix(m.timeDecoder?.weight,genes.length,h)||!matrix([m.timeDecoder?.bias],1,genes.length)||!matrix([m.rates?.beta],1,genes.length)||!matrix([m.rates?.gamma],1,genes.length)||!matrix(m.rates?.W,genes.length,genes.length)||!matrix([m.rates?.b],1,genes.length)||!matrix(m.rates?.alphaObserved,n,genes.length)||!Array.isArray(m.history))fail('时间解码器、动力学或训练记录缺失。');
  }
  if(bundle.status==='complete'&&indices.size!==expectedModelCount)fail(`完整结果必须含 ${expectedModelCount} 个模型。`);
  for(let a=1;a<bundle.models.length;a++){
    const first=bundle.models[0].samples,other=bundle.models[a].samples;
    if(first.length!==other.length||first.some((p,i)=>JSON.stringify(p.epsilon)!==JSON.stringify(other[i].epsilon)))fail('比较结果必须使用同一 ε 样本库。');
  }
  return bundle;
}

// A fixed order derived only from model 1's posterior means. The primary
// coordinate is z1 (far end first); z2 and z3 make ties deterministic.
export function modelOneCellOrder(bundle){
  const model=bundle.models.find(m=>m.index===0);
  if(!model)return bundle.data.cells.map((_,i)=>i);
  return model.mu.map((v,i)=>({i,v})).sort((a,b)=>b.v[0]-a.v[0]||b.v[1]-a.v[1]||b.v[2]-a.v[2]||a.i-b.i).map(x=>x.i);
}
export function replicaSelection(bundle,cell,sample,mode='sample',indices=[0,1,2]){
  return indices.map(index=>{
    const model=bundle.models.find(m=>m.index===index);
    if(!model)return {index,observation:bundle.data.cells[cell].raw,model:null};
    const selected=model.samples[sample%model.samples.length],pass=mode==='mean'?model.meanPass:selected;
    return {index,model,observation:bundle.data.cells[cell].raw,mu:model.mu[cell],variance:model.variance[cell],epsilon:mode==='mean'?[0,0,0]:selected.epsilon[cell],z:mode==='mean'?model.mu[cell]:selected.z[cell],prediction:pass.prediction[cell],time:pass.time[cell]};
  });
}

export function createReplicaLab(sourceBundle=stabilityReplicas,options={}){
  let bundle=validateReplicas(sourceBundle),cell=0,sample=0,mode='sample',orderMode='model1-z1',viewAngles=Array.from({length:Math.max(3,sourceBundle.expectedModelCount??sourceBundle.models?.length??3)},()=>({yaw:.5,pitch:.25})),zoom=Array(viewAngles.length).fill(1),showInitial=false,showGeometry=true,showEllipsoids=true,showHull=false,showMvee=false,showPoints=true,showFlow=false,orderedCells=modelOneCellOrder(bundle),route='replicas',backend=false,message='',pollTimer;
  const geneCount=bundle.data.genes.length,inputDim=bundle.data.featureOrder.length,featureOrder=bundle.data.featureOrder,cellCount=bundle.data.cells.length;
  const $=id=>document.getElementById(id),esc=replicaEscape,geometryCache=new WeakMap();
  const titles={replicas:options.title??'五组独立拟合 · 同一细胞的五个空间','replica-compare':'五组独立拟合 · 同一细胞的五个空间','replica-encoder':`模型 1 · ${inputDim}维输入怎样得到 μ 和 v`,'replica-training':'模型 1 · 训练怎样改变分布','replica-space':'模型 1 · 重参数化改变了什么','replica-kinetics':'模型 1 · 潜时间与两池动力学','replica-source':'完整 RegVelo · 结果与来源'};
  const modelIndices=()=>{const current=bundle.models.map(model=>model.index);return current.length?current:Array.from({length:sourceBundle.expectedModelCount??3},(_,i)=>i);};
  const fine=(scope,label)=>`<button data-rp-scope="${scope}" ${backend?'':'disabled'}>${label} · 微调 10 轮</button>`;
  function geometrySimilarity(){
    const models=bundle.models.filter(model=>Array.isArray(model.mu)&&model.mu.length===bundle.data.cells.length);
    if(models.length<2)return '';
    const signature=mu=>{const values=[];for(let i=0;i<mu.length-1;i++)for(let j=i+1;j<mu.length;j++)values.push(Math.hypot(...mu[i].map((v,k)=>v-mu[j][k])));const sorted=[...values].sort((a,b)=>a-b),scale=sorted[Math.floor(sorted.length/2)]||1;return values.map(v=>v/scale);};
    const signatures=models.map(model=>signature(model.mu)),correlation=(a,b)=>{const ma=a.reduce((s,v)=>s+v,0)/a.length,mb=b.reduce((s,v)=>s+v,0)/b.length,da=Math.sqrt(a.reduce((s,v)=>s+(v-ma)**2,0)),db=Math.sqrt(b.reduce((s,v)=>s+(v-mb)**2,0));return a.reduce((s,v,i)=>s+(v-ma)*(b[i]-mb),0)/(da*db||1);},values=[];
    for(let i=0;i<signatures.length-1;i++)for(let j=i+1;j<signatures.length;j++)values.push(correlation(signatures[i],signatures[j]));
    values.sort((a,b)=>a-b);const median=values[Math.floor(values.length/2)];return `<section class="panel rp-geometry-note"><h2>同一批观测，不同潜空间训练</h2><p>五个代表模型读取相同的 ${cellCount} 个细胞、${inputDim}维 S/U 观测、训练/验证划分和 RegVelo 生成路径，只改变随机种子；第一行模型 1 的编码器、时间解码器和动力学参数用于下面的具体讲解。</p><p>不同训练可能带来坐标朝向、中心和尺度的变化，因此比较采用 ${cellCount} 个细胞均值的两两距离签名，并按每个模型的中位距离归一化。Pearson（皮尔逊）相关范围为 <b>${replicaNumber(values[0])}–${replicaNumber(values.at(-1))}</b>，中位数为 <b>${replicaNumber(median)}</b>；这支持“几何结构相似”的描述，同时保留模型间差异。</p><p class="sub">比较对象是细胞间距离结构，不把不同模型的 z₁、z₂、z₃ 直接当成同一坐标轴。</p></section>`;
  }
  function whatToSee(){return `<section class="panel rp-reading-map" aria-label="本页看什么"><div class="rp-reading-head"><div><p class="eyebrow">READING MAP · 页面读法</p><h2>本页看什么</h2><p>先固定同一批合成样本，再观察不同潜空间训练如何保留细胞之间的几何关系；最后沿训练轮次回看损失和参数怎样变化。</p></div><span class="tag">教学模拟 + 实际导入结果</span></div><div class="rp-reading-flow"><article><span class="rp-reading-step">01</span><h3>同一批样本</h3><p>五行模型共享同一组 ${cellCount} 个细胞和${inputDim}维 S/U 观测。这样每一行的变化来自潜空间训练与随机初始化，样本本身保持不动。</p><span class="rp-reading-formula">x = (${featureOrder.join(String.fromCharCode(44))})</span></article><i aria-hidden="true">→</i><article><span class="rp-reading-step">02</span><h3>几何相似</h3><p>不同训练可能改变坐标朝向、中心或尺度，所以比较细胞间距离结构。Pearson（皮尔逊）相关越接近 1，说明相对几何更相似。</p><span class="rp-reading-formula">dᵢⱼ = ‖μᵢ − μⱼ‖₂</span></article><i aria-hidden="true">→</i><article><span class="rp-reading-step">03</span><h3>训练收敛</h3><p>epoch（训练轮次）增加时，loss（损失）通常下降并趋于平稳；参数更新变小，细胞潜位置和后验椭球也逐渐稳定。</p><span class="rp-reading-formula">θₜ₊₁ = θₜ − η∇<sub>θ</sub>L</span></article></div><div class="rp-reading-boundary"><b>画布可视化边界</b><span>canvas（画布）把抽象的点、椭球、损失曲线和训练轨迹画出来，便于教学观察。页面中的“实际导入结果”来自本地训练文件；若显示“教学模拟”，它只演示训练机制，不代表 RegVelo 保存的中间态。</span></div></section>`;}
  function parameterSummary(){
    const m=bundle.models.find(model=>model.index===0),r=replicaSelection(bundle,cell,sample,mode,modelIndices())[0];
    if(!m)return '';
    return `<section class="panel rp-parameter-note"><h2>第一行模型 1 的具体参数讲解</h2><p>下面的数值全部来自第一页第一行代表模型 1（seed ${m.stabilitySeed??m.seed}）的导出结果，不是重新拟合的教学占位值。编码器输出三维潜分布，解码器沿 RegVelo 的时间与 RNA 动力学路径生成${inputDim}维重构。</p><div class="rp-parameter-grid"><div><b>模型配置</b><span>n_latent = ${m.config.n_latent} · n_hidden = ${m.config.n_hidden} · t_max = ${replicaNumber(m.config.t_max)} · 训练 ${m.epochs} 轮 · 最佳轮 ${m.bestEpoch}</span></div><div><b>当前细胞 ${esc(bundle.data.cells[cell].id)}</b><span>μ = (${replicaVector(r.mu)}) · √v = (${replicaVector(r.variance.map(Math.sqrt))}) · z = (${replicaVector(r.z)})</span></div><div><b>${geneCount}基因动力学</b><span>β = (${replicaVector(m.rates.beta)}) · γ = (${replicaVector(m.rates.gamma)})</span></div><div><b>调控矩阵 W</b><span>${m.rates.W.map(row=>`(${replicaVector(row)})`).join(' · ')}</span></div></div><p class="sub">继续查看：<a href="#kinetics">DIY 训练、参数和动力学水池</a></p></section>`;
  }
  function controls(){return `<div class="rp-controls panel"><label>细胞顺序 <select id="rp-order"><option value="model1-z1" ${orderMode==='model1-z1'?'selected':''}>模型 1：μ 按 z1 远端起始，z2/z3 排序</option><option value="sample" ${orderMode==='sample'?'selected':''}>原始样本顺序</option></select></label><button id="rp-flow" aria-pressed="${showFlow}">${showFlow?'隐藏流线':'显示流线'}</button><span class="rp-order-note">固定顺序依次连接各模型的细胞均值；用于比较几何连续性，不表示速度方向。</span><label>同一细胞 <select id="rp-cell">${bundle.data.cells.map((c,i)=>`<option value="${i}" ${i===cell?'selected':''}>${esc(c.id)}</option>`).join('')}</select></label><label>前向输入 <select id="rp-mode"><option value="sample" ${mode==='sample'?'selected':''}>采样 z → 时间 → u/s</option><option value="mean" ${mode==='mean'?'selected':''}>均值 μ → 时间 → u/s</option></select></label><button id="rp-sample" ${bundle.models.length?'':'disabled'}>重抽 ε（不训练）</button><label><input id="rp-geometry" type="checkbox" ${showGeometry?'checked':''}> 坐标轴</label><label><input id="rp-ellipsoids" type="checkbox" ${showEllipsoids?'checked':''}> 每细胞后验椭球</label><label><input id="rp-hull" type="checkbox" ${showHull?'checked':''}> 凸包</label><label><input id="rp-mvee" type="checkbox" ${showMvee?'checked':''}> MVEE 包围椭球</label><label><input id="rp-points" type="checkbox" ${showPoints?'checked':''}> 细胞点 μ / z</label><label><input id="rp-initial" type="checkbox" ${showInitial?'checked':''}> 显示训练前分布</label><label>训练上限（epoch） <select id="rp-epochs"><option>100</option><option>500</option><option selected>1000</option><option>3000</option><option>10000</option></select></label><button id="rp-train" ${backend?'':'disabled'}>独立训练${modelIndices().length}个模型</button><label class="rp-import">导入实际结果 JSON <input id="rp-import" type="file" accept=".json,application/json"></label></div>`;}
  function grid(){return `<div class="rp-grid-head"><b>① 相同的${inputDim}维 S/U 观测 x = (s, u)</b><b>② 三维后验分布与采样点</b><b>③ 完整动力学解码得到${inputDim}维重构</b></div>${modelIndices().map(i=>{const m=bundle.models.find(model=>model.index===i);return `<section class="rp-model-row" aria-label="模型 ${i+1}"><div class="rp-row-label"><b>模型 ${i+1}</b><span>随机种子 ${m?.stabilitySeed??m?.seed??bundle.plannedSeeds?.[i]??'—'} · ${m?`训练 ${m.epochs} 轮 / 最佳验证轮 ${m.bestEpoch}`:'等待完整 RegVelo 训练'}</span>${i===0?'<strong>第一行代表模型 1：所有参数讲解读取此模型</strong>':'<span>独立拟合 · 自己的潜坐标系</span>'}</div><div class="rp-three"><article class="rp-chart-card"><h3>${inputDim}维 S/U 观测 · 所有行相同</h3><canvas id="rp-observed-${i}" width="420" height="270" aria-label="模型 ${i+1} ${inputDim}维 S/U 观测"></canvas><p>每条线是一个细胞，深色线是 ${esc(bundle.data.cells[cell].id)}。</p></article><article class="rp-chart-card"><div class="rp-latent-title"><h3>三维潜空间 · 模型 ${i+1}</h3><div class="rp-zoom" role="group" aria-label="模型 ${i+1} 潜空间缩放"><button type="button" data-rp-zoom="${i}" data-rp-zoom-step="-1" aria-label="模型 ${i+1} 缩小">−</button><output id="rp-zoom-value-${i}" aria-live="polite">100%</output><button type="button" data-rp-zoom="${i}" data-rp-zoom-step="1" aria-label="模型 ${i+1} 放大">+</button><button type="button" data-rp-zoom="${i}" data-rp-zoom-step="0" aria-label="模型 ${i+1} 缩放复位">复位</button></div></div><canvas id="rp-latent-${i}" width="420" height="270" tabindex="0" aria-label="三维后验椭球；方向键旋转视角"></canvas><p>${m?'坐标轴、凸包、MVEE、每细胞后验椭球与细胞点可独立开关；红色虚线椭球为训练前分布。':'等待真实 μ、v 和 z；此处保留空白。'}</p></article><article class="rp-chart-card"><h3>${inputDim}维重构 · 模型 ${i+1}</h3><canvas id="rp-decoded-${i}" width="420" height="270" aria-label="模型 ${i+1} 重构表达"></canvas><p>${m?'实线：当前前向重构；虚线：固定观测。':'等待真实潜时间与 ODE（常微分方程）输出。'}</p></article></div><p id="rp-values-${i}" class="rp-values"></p></section>`;}).join('')}`;}
  function detail(){
    const m=bundle.models.find(m=>m.index===0),r=replicaSelection(bundle,cell,sample,mode,modelIndices())[0],empty='<p class="rp-empty">模型 1 尚未训练完成。数值和曲线将在实际结果导入后出现。</p>';
    if(route==='replica-space')return `<section class="panel"><h2>模型 1：编码、训练与重参数化</h2><p>这一页把原先的编码器、训练和重参数化内容合并，沿同一个细胞追踪 ${inputDim} → 3 → ${inputDim} 的完整路径。</p><h3>① 编码器：固定输入对应一个分布</h3><p>x = (${featureOrder.join(String.fromCharCode(44))}) → ${m?.config.n_hidden??256} 个隐藏单元 → 三维均值 μ 和三维方差 v。</p><p>h = Encoder(x)； μ = W_μh + b_μ； v = softplus(W_vh + b_v) + δ。softplus 是保持方差为正的平滑函数。</p>${fine('encoder','编码器')}${m?`<p>当前输入：${replicaVector(m.encoder.input[cell])}</p><div class="rp-scroll"><table><thead><tr><th>维度</th><th>μ</th><th>v</th><th>√v</th></tr></thead><tbody>${[0,1,2].map(j=>`<tr><td>z${j+1}</td><td>${replicaNumber(r.mu[j])}</td><td>${replicaNumber(r.variance[j])}</td><td>${replicaNumber(Math.sqrt(r.variance[j]))}</td></tr>`).join('')}</tbody></table></div>`:empty}<h3>② 训练：中心、形状和动力学参数一起更新</h3><p>联合目标包含${inputDim}维重构项、KL（Kullback–Leibler，分布差异）项和 RegVelo 动力学约束；最佳验证轮恢复对应权重。</p>${fine('joint','模型 1 联合训练')}${m?`<p>实际训练 ${m.epochs} 轮；最佳验证轮 ${m.bestEpoch}。训练前 μ = (${replicaVector(m.initial.mu[cell])})；训练后 μ = (${replicaVector(r.mu)})。</p><canvas id="rp-history" width="900" height="280" aria-label="训练与验证损失曲线"></canvas>`:empty}<h3>③ 重参数化：同一 μ/v 下改变随机点</h3><p class="rp-formula">z = μ + √v ⊙ ε，ε ∼ N(0,I)</p><p>重新抽样只移动 z、潜时间和重构；μ 与 v 保持固定。它不会重新训练模型。</p>${m?`<table><thead><tr><th>维度</th><th>μ</th><th>√v</th><th>ε</th><th>z</th></tr></thead><tbody>${[0,1,2].map(j=>`<tr><td>z${j+1}</td><td>${replicaNumber(r.mu[j])}</td><td>${replicaNumber(Math.sqrt(r.variance[j]))}</td><td>${replicaNumber(r.epsilon[j])}</td><td>${replicaNumber(r.z[j])}</td></tr>`).join('')}</tbody></table>`:empty}</section>`;
    if(route==='replica-source')return `<section class="panel"><h2>结果可追溯</h2><p>输入沿用本网页 ${cellCount} 个合成细胞、${geneCount} 个基因和 ${inputDim} 维 S/U 观测。完整模型使用本地 RegVelo、scvi-tools（单细胞变分推断工具）和 torchode（可微分方程求解库）。先验调控网络为教学设置。</p><p>五组拟合共享观测、先验和训练/验证划分，随机种子由导出结果记录。模型参数与潜坐标独立保存。</p><pre>${esc(JSON.stringify(m?{config:m.config,source:m.source,versions:m.versions,observationSha256:m.observationSha256,split:m.split}:bundle.provenance,null,2))}</pre><p>本地运行：<code>python tools/setup_regvelo_runtime.py</code>；依赖就绪后运行 <code>python tools/serve_regvelo.py</code>。服务页面可触发训练；离线页可导入 <code>.runtime/regvelo-runs/replicas.json</code>。</p><p>浏览器不会把教学优化器的输出当作完整模型。导入会核验结构、共享 ε 和重参数化关系；来源记录用于追溯，不等于对外部文件的真实性认证。</p></section>`;
    if(route==='replica-encoder')return `<section class="panel"><h2>Encoder（编码器）：固定输入对应一个分布</h2><p>x = (${featureOrder.join(String.fromCharCode(44))}) → ${m?.config.n_hidden??256} 个隐藏单元 → 三维均值 μ 和三维方差 v。</p><p>h = Encoder(x)； μ = W_μ h + b_μ； v = softplus(W_v h + b_v) + δ。softplus 是保持方差为正的平滑函数。评估模式关闭 dropout（随机丢弃单元），相同输入的 μ/v 固定。</p>${fine('encoder','编码器')}${m?`<p>当前细胞输入：${replicaVector(m.encoder.input[cell])}</p><p>隐藏表示前 12 项：${replicaVector(m.encoder.hidden[cell].slice(0,12))} …（完整 ${m.config.n_hidden} 项）</p><div class="rp-scroll"><table><thead><tr><th>维度</th><th>均值头 W·h+b</th><th>μ</th><th>方差头 W·h+b</th><th>v</th><th>√v</th></tr></thead><tbody>${[0,1,2].map(j=>{const dot=(w,b)=>w.reduce((s,v,k)=>s+v*m.encoder.hidden[cell][k],b);return `<tr><td>z${j+1}</td><td>${replicaNumber(dot(m.encoder.meanWeight[j],m.encoder.meanBias[j]))}</td><td>${replicaNumber(r.mu[j])}</td><td>${replicaNumber(dot(m.encoder.varianceWeight[j],m.encoder.varianceBias[j]))}</td><td>${replicaNumber(r.variance[j])}</td><td>${replicaNumber(Math.sqrt(r.variance[j]))}</td></tr>`;}).join('')}</tbody></table></div>`:empty}</section>`;
    if(route==='replica-training')return `<section class="panel"><h2>训练会更新分布中心、形状和动力学参数</h2><p>每轮联合优化编码器、时间解码器和动力学参数。重构损失、KL（Kullback–Leibler，分布差异）项以及本地源码的正则项共同影响梯度。</p><p>最佳轮数根据相同验证集的 ELBO（证据下界）损失选择，并恢复该轮权重。训练上限允许增加，具体最佳轮数由验证指标决定。</p>${fine('joint','模型 1 联合训练')}${m?`<p>完成 ${m.epochs} 轮；最佳验证轮：${m.bestEpoch}。训练前 μ = (${replicaVector(m.initial.mu[cell])})；训练后 μ = (${replicaVector(r.mu)})。</p><p>训练前 √v = (${replicaVector(m.initial.variance[cell].map(Math.sqrt))})；训练后 √v = (${replicaVector(r.variance.map(Math.sqrt))})。</p><canvas id="rp-history" width="900" height="280" aria-label="实际训练和验证损失曲线"></canvas><p>蓝线：训练 ELBO 损失；橙线：验证 ELBO 损失。横轴是实际轮数。</p><pre>${esc(JSON.stringify(m.history.slice(-5),null,2))}</pre>`:empty}</section>`;
    if(route==='replica-kinetics')return `<section class="panel"><h2>Latent time（潜时间）：从 z 到两池状态</h2><p>z → 时间解码器 → 逐基因 t = t_max · sigmoid(W_t h_t + b_t) → 耦合两池方程 → 重构 (s, u)。这些时间由模型学习；${geneCount}个基因保留各自的时间输出。</p><p>du_g/dt = α_g(s) − β_g u_g； ds_g/dt = β_g u_g − γ_g s_g。</p><p>β 是剪接率，γ 是降解率；它们是跨细胞共享的逐基因参数。α(s) 由调控权重 W、偏置 b 和表达状态确定。同一个采样 ε 会改变整组三维 z，再经网络影响${geneCount}个基因的时间与重构。</p>${fine('time','时间解码器')} ${fine('rates','动力学参数')} ${fine('grn','调控网络')} ${fine('beta','剪接率 β')} ${fine('gamma','降解率 γ')}${m?`<table><thead><tr><th>基因</th><th>β</th><th>γ</th><th>α(观测 s)</th><th>当前潜时间 t</th><th>重构 s</th><th>重构 u</th></tr></thead><tbody>${Array.from({length:geneCount},(_,j)=>`<tr><td>${bundle.data.genes[j]}</td><td>${replicaNumber(m.rates.beta[j])}</td><td>${replicaNumber(m.rates.gamma[j])}</td><td>${replicaNumber(m.rates.alphaObserved[cell][j])}</td><td>${replicaNumber(r.time[j])}</td><td>${replicaNumber(r.prediction[j])}</td><td>${replicaNumber(r.prediction[j+geneCount])}</td></tr>`).join('')}</tbody></table><p>α(观测 s) 仅是在输入成熟表达处计算的转录率；ODE 轨迹会在沿途状态重新计算 α。上表的${geneCount}个潜时间也不应视为同一整体瞬时状态。</p><pre>W（行：靶基因；列：调控基因）\n${esc(m.rates.W.map(replicaVector).join('\n'))}\nb = ${replicaVector(m.rates.b)}</pre>`:empty}</section>`;
    return `<section class="panel rp-focus"><h2>固定模型和细胞，重新抽 ε 会发生什么</h2><p>Posterior（后验分布）是模型给定该细胞观测后学到的潜变量分布：q_φ(z_i | x_i) = N(μ_i, diag(v_i))。</p><p class="rp-formula">z_i = μ_i + √v_i ⊙ ε_i， ε_i ∼ N(0, I)</p><p>Reparameterization（重参数化）把随机性放进 ε，训练时梯度可以沿 μ 和 v 回传。同一细胞的三个潜坐标一起抽样，所有基因共同参与拟合。</p><p><b>冻结权重再重抽 ε：</b>椭球的中心 μ、半轴 √v 都保持固定，橙色采样点移动，潜时间与重构可能随之变化。<b>继续训练或换一个独立模型：</b>μ/v 以及动力学参数都可能改变。</p>${m?`<table><thead><tr><th>模型 1 的维度</th><th>μ（中心）</th><th>√v（半轴）</th><th>ε（噪声）</th><th>z = μ + √v·ε</th></tr></thead><tbody>${[0,1,2].map(j=>`<tr><td>z${j+1}</td><td>${replicaNumber(r.mu[j])}</td><td>${replicaNumber(Math.sqrt(r.variance[j]))}</td><td>${replicaNumber(r.epsilon[j])}</td><td>${replicaNumber(r.z[j])}</td></tr>`).join('')}</tbody></table><p>潜时间 (${replicaVector(r.time)})；重构 (${replicaVector(r.prediction)})。当前为${mode==='mean'?'均值输入前向；它通常不等于后验预测平均':'实际导出的第 '+(sample+1)+' / '+m.samples.length+' 个 ε 前向；样本库用完后循环'}。</p>`:empty}<p>三个独立模型的坐标方向、尺度和神经网络权重可能不同。逐行观察同一细胞的分布，参数讲解始终取模型 1。</p><p>椭球画的是马氏距离为 1 的等密度面，在三维高斯中包围约 19.9% 概率；细胞采样点可以落在椭球外。</p></section>`;
  }
  function template(requested){route=requested;return `<div class="rp-page"><div class="page-intro"><p class="eyebrow">COMPLETE REGVELO · 五组代表模型独立拟合</p><h1>${titles[route]}</h1><p>同一份${inputDim}维 S/U 合成观测 · 三维潜变量 · 所有参数讲解固定使用模型 1</p></div>${route==='replicas'?whatToSee():''}${route==='replicas'?'':'<p id="rp-status" class="panel rp-status" role="status"></p>'}${controls()}${route==='replicas'||route==='replica-compare'?grid():''}${route==='replicas'?geometrySimilarity()+parameterSummary():''}<div id="rp-detail">${detail()}</div><p class="rp-legacy">旧版教学入口：<a href="#overview">三空间总览</a> · <a href="#encoder">编码与解码</a> · <a href="#training">拟合过程</a> · <a href="#space">潜空间</a> · <a href="#kinetics">两池实验</a> · <a href="#construction">源码对应</a></p></div>`;}
  function canvas(id){const c=$(id);if(!c)return null;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#f7fafc';ctx.fillRect(0,0,w,h);return {ctx,w,h};}
  function expression(id,all,selected,observed=null){const p=canvas(id);if(!p)return;const {ctx,w,h}=p,max=Math.max(1,...bundle.data.cells.flatMap(c=>c.raw),...bundle.models.flatMap(m=>[...m.meanPass.prediction.flat(),...m.samples.flatMap(s=>s.prediction.flat())])),x=j=>35+j*(w-60)/Math.max(1,inputDim-1),y=v=>h-36-v*(h-65)/max;ctx.strokeStyle='#dbe4ed';ctx.fillStyle='#53667b';ctx.font='11px sans-serif';for(let j=0;j<inputDim;j++){ctx.beginPath();ctx.moveTo(x(j),20);ctx.lineTo(x(j),h-30);ctx.stroke();ctx.fillText(featureOrder[j],x(j)-18,h-12);}ctx.fillText(max.toFixed(1),4,24);ctx.fillText('0',15,h-33);const line=(values,color,width,dash=[])=>{ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(dash);ctx.beginPath();values.forEach((v,j)=>j?ctx.lineTo(x(j),y(v)):ctx.moveTo(x(j),y(v)));ctx.stroke();ctx.setLineDash([]);};all.forEach(v=>line(v,'#c1ceda',.8));if(observed)line(observed,'#8b6b49',2,[5,4]);if(selected)line(selected,'#1568a0',3);else if(!all.length){ctx.fillStyle='#687b8c';ctx.fillText('等待完整 RegVelo 重构',105,h/2);}}
  function latent(id,r){
    const p=canvas(id);if(!p)return;const {ctx,w,h}=p;
    if(!r.model){ctx.fillStyle='#687b8c';ctx.font='14px sans-serif';ctx.fillText('等待完整 RegVelo 的 μ、v、z',100,h/2);return;}
    const m=r.model,angle=viewAngles[r.index],points=[...m.mu,...m.samples[sample%m.samples.length].z];
    let geometry=geometryCache.get(m);if(!geometry){geometry={hull:convexHull3D(m.mu),mvee:minimumVolumeEnclosingEllipsoid3D(m.mu)};geometryCache.set(m,geometry);}
    const span=Math.max(1,...points.flat().map(Math.abs),...m.mu.flatMap((q,i)=>q.map((v,j)=>Math.abs(v)+2*Math.sqrt(m.variance[i][j]))),...(showInitial?m.initial.mu.flatMap((q,i)=>q.map((v,j)=>Math.abs(v)+Math.sqrt(m.initial.variance[i][j]))):[]),...(showMvee?geometry.mvee.center.map((v,j)=>Math.abs(v)+geometry.mvee.extent[j]):[]));
    const scale=Math.min(w,h)*.39*zoom[r.index]/span;
    const frame=orientLatentProjection(m.mu[0],m.variance[0],angle.yaw,angle.pitch),orient=frame.rotate;
    const to=v=>{const q=orient(rotateLatent(v,angle.yaw,angle.pitch));return [w/2+q[0]*scale,h/2-q[1]*scale];};
    ctx.font='11px sans-serif';
    if(showGeometry){for(let j=0;j<3;j++){const v=[0,0,0];v[j]=span;const q=to(v);ctx.strokeStyle='#bcc8d5';ctx.beginPath();ctx.moveTo(w/2,h/2);ctx.lineTo(...q);ctx.stroke();ctx.fillStyle='#53667b';ctx.fillText('z'+(j+1),...q);}}
    const project3=v=>{const q=orient(rotateLatent(v,angle.yaw,angle.pitch));return [w/2+q[0]*scale,h/2-q[1]*scale,rotateLatent(v,angle.yaw,angle.pitch)[2]];};
    const paintTriangles=(triangles,fill)=>{const projected=triangles.map(triangle=>triangle.map(project3)).sort((a,b)=>a.reduce((sum,p)=>sum+p[2],0)-b.reduce((sum,p)=>sum+p[2],0));ctx.save();ctx.fillStyle=fill;for(const tri of projected){ctx.beginPath();ctx.moveTo(tri[0][0],tri[0][1]);ctx.lineTo(tri[1][0],tri[1][1]);ctx.lineTo(tri[2][0],tri[2][1]);ctx.closePath();ctx.fill();}ctx.restore();};
    if(showHull){paintTriangles(geometry.hull.faces.map(face=>face.map(i=>m.mu[i])),'rgba(20,143,143,.13)');ctx.save();ctx.strokeStyle='rgba(14,111,119,.65)';ctx.lineWidth=1.1;for(const [a,b] of geometry.hull.edges){const p=project3(m.mu[a]),q=project3(m.mu[b]);ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(q[0],q[1]);ctx.stroke();}ctx.restore();}
    if(showMvee){const shape=geometry.mvee,point=(lat,lon)=>shape.center.map((v,j)=>v+shape.vectors[j].reduce((sum,axis,k)=>sum+axis*(k===0?shape.axes[0]*Math.cos(lat)*Math.cos(lon):k===1?shape.axes[1]*Math.cos(lat)*Math.sin(lon):shape.axes[2]*Math.sin(lat)),0));
      const latitudes=Array.from({length:9},(_,i)=>-Math.PI/2+i*Math.PI/8),longitudes=Array.from({length:25},(_,i)=>i*Math.PI/12),triangles=[];
      for(let a=0;a<latitudes.length-1;a++)for(let b=0;b<longitudes.length-1;b++){const p00=point(latitudes[a],longitudes[b]),p01=point(latitudes[a],longitudes[b+1]),p10=point(latitudes[a+1],longitudes[b]),p11=point(latitudes[a+1],longitudes[b+1]);triangles.push([p00,p10,p11],[p00,p11,p01]);}
      paintTriangles(triangles,'rgba(105,91,184,.105)');ctx.save();ctx.strokeStyle='rgba(92,77,162,.62)';ctx.lineWidth=.85;
      for(const lat of [-Math.PI/3,-Math.PI/6,0,Math.PI/6,Math.PI/3]){ctx.beginPath();longitudes.forEach((lon,k)=>{const q=project3(point(lat,lon));k?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]);});ctx.stroke();}
      for(let k=0;k<12;k++){ctx.beginPath();latitudes.forEach((lat,j)=>{const q=project3(point(lat,k*Math.PI/12));j?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]);});ctx.stroke();}ctx.restore();}
    function ellipsoid(mu,variance,color,fill=false,wire=false){
      const shape=projectEllipsoid(mu,variance,1,angle.yaw,angle.pitch),center=to(mu);
      ctx.beginPath();ctx.ellipse(...center,Math.max(.2,shape.radii[0]*scale),Math.max(.2,shape.radii[1]*scale),0,0,Math.PI*2);ctx.strokeStyle=color;ctx.lineWidth=fill?2:1;
      if(fill){ctx.fillStyle='#247ba024';ctx.fill();}ctx.stroke();if(!wire)return;
      const surface=(lat,lon)=>{const u=[Math.cos(lat)*Math.cos(lon),Math.cos(lat)*Math.sin(lon),Math.sin(lat)];return mu.map((v,j)=>v+Math.sqrt(Math.max(1e-9,variance[j]))*u[j]);};
      const wireLine=pts=>{ctx.save();ctx.strokeStyle=color;ctx.globalAlpha=fill?.42:.18;ctx.lineWidth=.7;ctx.beginPath();pts.forEach((v,k)=>{const q=to(v);k?ctx.lineTo(...q):ctx.moveTo(...q);});ctx.stroke();ctx.restore();};
      for(const lat of [0])wireLine(Array.from({length:49},(_,k)=>surface(lat,k*Math.PI/24)));
      for(const lon of [0,Math.PI/2])wireLine(Array.from({length:33},(_,k)=>surface(-Math.PI/2+k*Math.PI/16,lon)));
    }
    if(showEllipsoids){m.mu.forEach((mu,i)=>{if(i!==cell)ellipsoid(mu,m.variance[i],'#bdcddd',false,false);});
      ellipsoid(r.mu,r.variance,'#1568a0',true,true);
    }
    if(showInitial){ctx.save();ctx.setLineDash([5,4]);ellipsoid(m.initial.mu[cell],m.initial.variance[cell],'#d64545');ctx.restore();}
    const dot=(v,color,size)=>{ctx.fillStyle=color;ctx.beginPath();ctx.arc(...to(v),size,0,Math.PI*2);ctx.fill();};
    if(showPoints){m.mu.forEach(v=>dot(v,'#8b9fb0',2));m.samples.forEach(q=>dot(q.z[cell],'#e7bd91',2));}
    if(showFlow){
      ctx.save();ctx.strokeStyle='#cc6c33';ctx.globalAlpha=.84;ctx.lineWidth=2;ctx.setLineDash([5,4]);ctx.beginPath();
      orderedCells.forEach((index,k)=>{const q=to(m.mu[index]);k?ctx.lineTo(...q):ctx.moveTo(...q);});ctx.stroke();ctx.setLineDash([]);
      orderedCells.forEach((index,k)=>{const q=to(m.mu[index]);ctx.fillStyle=k===0?'#9a4d9d':'#cc6c33';ctx.beginPath();ctx.arc(...q,k===0?4:2.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#80553c';ctx.font='9px sans-serif';ctx.fillText(String(k+1),q[0]+5,q[1]-4);});ctx.restore();}
    if(showPoints){ctx.strokeStyle='#cf7c2f';ctx.beginPath();ctx.moveTo(...to(r.mu));ctx.lineTo(...to(r.z));ctx.stroke();dot(r.mu,'#1568a0',5);dot(r.z,'#df7b24',5);}
  }
  function historyPlot(){const p=canvas('rp-history'),m=bundle.models.find(m=>m.index===0);if(!p||!m)return;const {ctx,w,h}=p,keys=['elbo_train','elbo_validation'],values=m.history.flatMap(r=>keys.map(k=>r[k]).filter(Number.isFinite));if(!values.length)return;const low=Math.min(...values),high=Math.max(...values),maxEpoch=Math.max(...m.history.map(r=>r.epoch),1);ctx.font='12px sans-serif';ctx.fillStyle='#53667b';ctx.fillText(replicaNumber(high),5,18);ctx.fillText(replicaNumber(low),5,h-25);for(let k=0;k<2;k++){ctx.strokeStyle=['#1568a0','#df7b24'][k];ctx.beginPath();let begun=false;for(const r of m.history)if(Number.isFinite(r[keys[k]])){const x=75+r.epoch/maxEpoch*(w-100),y=h-35-(r[keys[k]]-low)/(high-low||1)*(h-65);begun?ctx.lineTo(x,y):ctx.moveTo(x,y);begun=true;}ctx.stroke();}ctx.fillText('epoch 1',75,h-10);ctx.fillText(String(maxEpoch),w-50,h-10);}
  function draw(){const rows=replicaSelection(bundle,cell,sample,mode,modelIndices());rows.forEach(r=>{expression(`rp-observed-${r.index}`,bundle.data.cells.map(c=>c.raw),r.observation);latent(`rp-latent-${r.index}`,r);expression(`rp-decoded-${r.index}`,[],r.prediction,r.model?r.observation:null);const p=$(`rp-values-${r.index}`);if(p)p.textContent=r.model?`μ = (${replicaVector(r.mu)}) · √v = (${replicaVector(r.variance.map(Math.sqrt))}) · z = (${replicaVector(r.z)})`:'μ / v / z / 重构：尚无实际训练结果';});historyPlot();}
  function status(){const p=$('rp-status');if(p)p.textContent=message||`${bundle.models.length} / ${Number.isInteger(sourceBundle.expectedModelCount)?sourceBundle.expectedModelCount:3} 个完整模型已导入。${bundle.blocker??''} ${backend?'本地训练服务已连接。':'离线模式：可导入结果；训练与微调需本地 Python 服务及依赖就绪。'}`;}
  function refresh(){const detailNode=$('rp-detail');if(detailNode)detailNode.innerHTML=detail();bindFine();draw();status();}
  async function requestTrain(scope,all=false){message='正在提交完整 Python RegVelo 训练任务…';status();try{const response=await fetch('/api/train',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope,all,epochs:all?Number($('rp-epochs').value):10})});const result=await response.json();if(!response.ok)throw Error(result.error??'训练请求失败');message='Python 训练已启动。可继续查看已完成结果，完成后自动载入。';status();pollTimer=setTimeout(poll,1500);}catch(e){message=e.message;status();}}
  function bindFine(){document.querySelectorAll('[data-rp-scope]').forEach(b=>{b.disabled=!backend||!bundle.models.some(m=>m.index===0);b.onclick=()=>requestTrain(b.dataset.rpScope);});}
  async function poll(){try{const response=await fetch('/api/status'),s=await response.json();backend=s.ready&&!s.running;const train=$('rp-train');if(train)train.disabled=!backend;bindFine();if(s.running){message='完整 RegVelo 训练中：'+JSON.stringify(s.progress??[]);status();pollTimer=setTimeout(poll,2000);}else if(s.hasResults){const response=await fetch('/api/results');bundle=validateReplicas(await response.json());message=s.error?'训练未完成：'+s.error:'已载入本地实际训练结果。';rerender();}else{message=s.error||s.preflight?.incompatible?.join('；')||s.preflight?.importError||s.preflight?.reason||'';status();}}catch{backend=false;status();}}
  function rerender(){const main=$('main');if(main){main.innerHTML=template(route);setup(route,false);}}
  function setup(requested,connect=true){route=requested;$('rp-geometry').onchange=()=>{showGeometry=$('rp-geometry').checked;draw();};$('rp-ellipsoids').onchange=()=>{showEllipsoids=$('rp-ellipsoids').checked;draw();};$('rp-hull').onchange=()=>{showHull=$('rp-hull').checked;draw();};$('rp-mvee').onchange=()=>{showMvee=$('rp-mvee').checked;draw();};$('rp-points').onchange=()=>{showPoints=$('rp-points').checked;draw();};$('rp-order').onchange=()=>{orderMode=$('rp-order').value;orderedCells=orderMode==='sample'?bundle.data.cells.map((_,i)=>i):modelOneCellOrder(bundle);draw();};$('rp-flow').onclick=()=>{showFlow=!showFlow;$('rp-flow').textContent=showFlow?'隐藏流线':'显示流线';$('rp-flow').setAttribute('aria-pressed',String(showFlow));draw();};$('rp-cell').onchange=()=>{cell=Number($('rp-cell').value);refresh();};$('rp-mode').onchange=()=>{mode=$('rp-mode').value;refresh();};$('rp-sample').onclick=()=>{const n=bundle.models[0]?.samples.length??1;sample=(sample+1)%n;mode='sample';$('rp-mode').value=mode;refresh();};$('rp-initial').onchange=()=>{showInitial=$('rp-initial').checked;draw();};$('rp-train').onclick=()=>requestTrain('joint',true);$('rp-import').onchange=async()=>{try{const file=$('rp-import').files[0];if(!file)return;if(file.size>50*1024*1024)throw Error('结果文件超过 50 MB。');const next=validateReplicas(JSON.parse(await file.text()));bundle=next;orderedCells=orderMode==='sample'?bundle.data.cells.map((_,i)=>i):modelOneCellOrder(bundle);cell=0;sample=0;message='已导入实际结果；参数讲解读取模型 1。';rerender();}catch(e){message='导入失败：'+e.message;status();}};document.querySelectorAll('[data-rp-zoom]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.rpZoom),step=Number(button.dataset.rpZoomStep);zoom[i]=step===0?1:Math.min(4,Math.max(.5,zoom[i]*Math.pow(1.25,step)));const value=$(`rp-zoom-value-${i}`);if(value)value.textContent=`${Math.round(zoom[i]*100)}%`;draw();});modelIndices().forEach(i=>{const c=$(`rp-latent-${i}`);if(c){let pointer=null,dragged=false;c.onpointerdown=e=>{pointer={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY};dragged=false;c.setPointerCapture?.(e.pointerId);};c.onpointermove=e=>{if(!pointer)return;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(Math.hypot(e.clientX-pointer.startX,e.clientY-pointer.startY)>3)dragged=true;if(dragged){viewAngles[i].yaw+=dx*.0035;viewAngles[i].pitch=Math.max(-1.5,Math.min(1.5,viewAngles[i].pitch+dy*.0035));draw();}pointer.x=e.clientX;pointer.y=e.clientY;};c.onpointerup=()=>{pointer=null;};c.onpointercancel=()=>{pointer=null;};c.onkeydown=e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();if(e.key==='ArrowLeft')viewAngles[i].yaw-=.08;if(e.key==='ArrowRight')viewAngles[i].yaw+=.08;if(e.key==='ArrowUp')viewAngles[i].pitch-=.08;if(e.key==='ArrowDown')viewAngles[i].pitch+=.08;draw();};c.onclick=e=>{if(dragged)return;const m=bundle.models.find(m=>m.index===i);if(!m)return;const box=c.getBoundingClientRect(),x=(e.clientX-box.left)*c.width/box.width,y=(e.clientY-box.top)*c.height/box.height;const points=[...m.mu,...m.samples[sample%m.samples.length].z],span=Math.max(1,...points.flat().map(Math.abs),...m.mu.flatMap((p,k)=>p.map((v,j)=>Math.abs(v)+2*Math.sqrt(m.variance[k][j]))),...(showInitial?m.initial.mu.flatMap((p,k)=>p.map((v,j)=>Math.abs(v)+Math.sqrt(m.initial.variance[k][j]))):[])),scale=Math.min(c.width,c.height)*.39*zoom[i]/span;let best=Infinity;m.mu.forEach((v,k)=>{const q=rotateLatent(v,viewAngles[i].yaw,viewAngles[i].pitch),d=Math.hypot(x-c.width/2-q[0]*scale,y-c.height/2+q[1]*scale);if(d<best){best=d;cell=k;}});$('rp-cell').value=String(cell);refresh();};}});refresh();if(connect&&typeof location!=='undefined'&&/^https?:$/.test(location.protocol))poll();}
  function stop(){clearTimeout(pollTimer);}
  return {template,setup,refresh,stop,state:()=>({bundle,selected:cell,sample,mode,showGeometry,showEllipsoids,showHull,showMvee,showPoints,showFlow,orderedCells:[...orderedCells],viewAngles:viewAngles.map(v=>({...v})),zoom:[...zoom],explanationModel:bundle.models.find(m=>m.index===0)??null,rows:replicaSelection(bundle,cell,sample,mode,modelIndices())})};
}
